mapper.select:
select USERUNIQUE, MONEY
from adofuser
where userunique in
      (select USERUNIQUE from gamegroupmember where groupname=#{groupName})
  and PERIOD=#{period}
  and marketname=#{marketName}
  and productname=#{productName}
  and MONEY > 0

select MONEY
from adofuser
where USERUNIQUE=#{userUnique}
  and PERIOD=#{period}
  and MARKETNAME=#{marketName}
  and PRODUCTNAME=#{productName}
